
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_gg99_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_gg99", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.293594130403129e+00, -4.213777733851070e+00, -4.102081760287484e+00, -3.947660020450801e+00, -3.737877085924069e+00, -3.459992114735187e+00, -3.105009959768544e+00, -2.674323870936646e+00, -2.187235365067640e+00, -1.677594873875933e+00, -1.149470984681768e+00, -7.125454694873282e-01, -5.983655910399541e-01, -5.044703321791594e-01, -3.810210891289658e-01, -2.628365795513008e-01, -1.734065557056108e-01, -1.138133388662806e-01, 0.000000000000000e+00, 0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


